<?php
namespace App\Livewire\Documents;
use App\Domain\Storage\Services\SecurePdfIngestor;use App\Jobs\ProcessDocumentMaster;use App\Models\Document;use Livewire\Attributes\Layout;use Livewire\Component;use Livewire\WithFileUploads;
#[Layout('layouts.app')]
class UploadPdf extends Component{use WithFileUploads;public Document $document;public $pdf;public function mount(Document $document):void{$this->document=$document->load('barcode');abort_unless(app(\App\Domain\Authorization\Services\PermissionResolver::class)->allows(auth()->user(),'documents.upload'),403);abort_unless(in_array($document->status->value,['AWAITING_UPLOAD','PROCESSING_FAILED','QC_REJECTED','VERIFICATION_REJECTED'],true),409);}public function save(SecurePdfIngestor $ingestor):void{$this->validate(['pdf'=>['required','file','mimes:pdf','max:'.config('dms.max_upload_kb')]]);try{$file=$ingestor->ingest($this->document,$this->pdf,auth()->id());\App\Jobs\GenerateDocumentDerivatives::dispatch($file->id);session()->flash('success','Archival master accepted and queued for preservation processing.');$this->redirectRoute('documents.show',$this->document,navigate:true);}catch(\Throwable $e){report($e);$this->addError('pdf',$e->getMessage());}}public function render(){return view('livewire.documents.upload-pdf');}}
